#!/usr/bin/env node
/**
 * Generates syntaxes/cure.tmLanguage.json.
 *
 * The keyword vocabulary comes from tree-sitter-cure/keywords.js (generated by
 * `mix cure.editors.sync`), and the token rules mirror
 * tree-sitter-cure/grammar.js and its highlight queries, so VS Code
 * highlights the same words the Zed and Neovim grammars do. Edit this
 * file, not the JSON, and run `npm run build-grammar` (also part of
 * `npm run compile`). `--check` exits non-zero when the JSON is out of date.
 */

const fs = require('fs');
const path = require('path');
const { KEYWORDS, WORD_OPERATORS, CONTAINERS } = require('../../tree-sitter-cure/keywords');

const OUTPUT = path.join(__dirname, '..', 'syntaxes', 'cure.tmLanguage.json');

// Keywords that head a type-level declaration (`type_declaration` in grammar.js).
const TYPE_DECLARATIONS = ['type', 'typealias', 'rec', 'interface', 'implementation', 'proto', 'impl'];

const escape = word => word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const words = list => `\\b(?:${list.map(escape).join('|')})\\b`;

const IDENT = '[a-z_][a-zA-Z0-9_$]*\\??';
const TYPE = '[A-Z][a-zA-Z0-9_]*';
const MODULE = `${TYPE}(?:\\.${TYPE})*`;

// An identifier that is not a keyword or declaration head, for the
// positional patterns below.
const PLAIN_IDENT = `(?!${words([...KEYWORDS, ...CONTAINERS, 'macro'])})${IDENT}`;

// The token before a regex literal. Oniguruma needs each look-behind
// alternative to have a fixed width, so the context is spelled out.
const REGEX_START = '(?:' + [
  '(?<=[^=<>!:|&^~\\\\+\\-*/.%$?]=)',
  '(?<=[^-]->)',
  '(?<==>)',
  '(?<=\\|>)',
  '(?<=[^:]:)',
  '(?<=[^|\\-]\\|)',
  '(?<=[,;(\\[{])',
  '(?<=\\breturn)',
].join('|') + ')';

const controlKeywords =KEYWORDS.filter(k => !WORD_OPERATORS.includes(k));
const wordOperators = KEYWORDS.filter(k => WORD_OPERATORS.includes(k));

const grammar = {
  $schema: 'https://raw.githubusercontent.com/martinring/tmlanguage/master/tmlanguage.json',
  name: 'Cure',
  scopeName: 'source.cure',
  patterns: [{ include: '#code' }],
  repository: {
    code: {
      patterns: [
        { include: '#comments' },
        { include: '#strings' },
        { include: '#chars' },
        { include: '#regexes' },
        { include: '#declarations' },
        { include: '#contextual' },
        { include: '#macro_vocabulary' },
        { include: '#decorators' },
        { include: '#transitions' },
        { include: '#keywords' },
        { include: '#constants' },
        { include: '#atoms' },
        { include: '#numbers' },
        { include: '#holes' },
        { include: '#calls' },
        { include: '#identifiers' },
        { include: '#types' },
        { include: '#groups' },
        { include: '#operators' },
        { include: '#punctuation' },
      ],
    },

    // `#` line comments, `##` doc lines, and `###` fences that close at the
    // next line starting with `###`.
    comments: {
      patterns: [
        {
          name: 'comment.block.documentation.cure',
          begin: '###',
          end: '^\\s*###.*$',
        },
        { name: 'comment.line.documentation.cure', match: '##.*$' },
        { name: 'comment.line.number-sign.cure', match: '#.*$' },
      ],
    },

    strings: {
      name: 'string.quoted.double.cure',
      begin: '"',
      end: '"',
      patterns: [
        { name: 'constant.character.escape.cure', match: '\\\\.' },
        {
          name: 'meta.embedded.line.cure',
          contentName: 'source.cure',
          begin: '#\\{',
          end: '\\}',
          beginCaptures: { 0: { name: 'punctuation.section.embedded.begin.cure' } },
          endCaptures: { 0: { name: 'punctuation.section.embedded.end.cure' } },
          patterns: [{ include: '#code' }],
        },
      ],
    },

    chars: {
      name: 'constant.character.cure',
      match: "'''|'[^'\\\\\\n]'|'\\\\.[^'\\n]*'",
    },

    // `/.../flags`. A `/` opens a regex only where an expression can begin
    // (after `=`, `->`, `=>`, `:`, `|`, `|>`, `,`, `;`, an opening bracket or
    // `return`, as in the lexer's `regex_literal_start?`), and divides
    // everywhere else.
    regexes: {
      match: `${REGEX_START}\\s*(/(?:[^/\\\\\\n]|\\\\.)*/[imsxufrUE]*)`,
      captures: { 1: { name: 'string.regexp.cure' } },
    },

    declarations: {
      patterns: [
        {
          match: `\\b(mod)\\s+(${MODULE})`,
          captures: {
            1: { name: 'keyword.control.cure' },
            2: { name: 'entity.name.namespace.cure' },
          },
        },
        {
          match: `\\b(fn)\\s+(${IDENT}|\`[^\`\\n]*\`)`,
          captures: {
            1: { name: 'storage.type.function.cure' },
            2: { name: 'entity.name.function.cure' },
          },
        },
        {
          match: `(${words(TYPE_DECLARATIONS)})\\s+(${TYPE})`,
          captures: {
            1: { name: 'keyword.control.cure' },
            2: { name: 'entity.name.type.cure' },
          },
        },
        // Containers are identifiers unless they head a declaration.
        {
          match: `(${words(CONTAINERS)})\\s+(${MODULE})`,
          captures: {
            1: { name: 'storage.type.cure' },
            2: { name: 'entity.name.type.cure' },
          },
        },
        {
          match: `\\b(macro)\\s+(${MODULE}|${IDENT})`,
          captures: {
            1: { name: 'storage.type.cure' },
            2: { name: 'entity.name.function.macro.cure' },
          },
        },
      ],
    },

    // Contextual keywords are identifiers to the lexer; each is matched only
    // in the position that makes it a keyword.
    contextual: {
      patterns: [
        { match: '^\\s*(have)\\s+(?=[a-z_])', captures: { 1: { name: 'keyword.control.cure' } } },
        { match: '\\b(requires)\\s+(?=[A-Z])', captures: { 1: { name: 'keyword.control.cure' } } },
        { match: '^\\s*(precedencegroup)\\s+(?=[A-Z])', captures: { 1: { name: 'keyword.control.cure' } } },
        { match: '^\\s*(infix|prefix|postfix)\\s+(?=`)', captures: { 1: { name: 'keyword.control.cure' } } },
        {
          match: '\\b(proof)\\s+(chain)\\b',
          captures: { 1: { name: 'keyword.control.cure' }, 2: { name: 'keyword.control.cure' } },
        },
        { match: '^\\s*(because)\\b', captures: { 1: { name: 'keyword.control.cure' } } },
        { match: '^\\s*(on_[a-z_]+)\\b', captures: { 1: { name: 'keyword.other.special.cure' } } },
      ],
    },

    // Macro entries: these words only mean something at the start of a line.
    macro_vocabulary: {
      patterns: [
        {
          match: '^\\s*(syntax)\\s+(family)\\b',
          captures: { 1: { name: 'keyword.control.cure' }, 2: { name: 'keyword.control.cure' } },
        },
        {
          match: `^\\s*(syntax|example|literal)\\s+(${PLAIN_IDENT})`,
          captures: { 1: { name: 'keyword.control.cure' }, 2: { name: 'entity.name.function.macro.cure' } },
        },
        {
          // `(?:^\\s*)?` so it starts where the line-start patterns below do and
          // wins on order.
          match: `(?:^\\s*)?\\b(expands\\s+with|computed(?:\\s+directly)?\\s+by)\\s+(${IDENT})`,
          captures: { 1: { name: 'keyword.control.cure' }, 2: { name: 'entity.name.function.cure' } },
        },
        {
          match: `^\\s*(optional|repeated|one_or_more)\\s+(${PLAIN_IDENT})`,
          captures: { 1: { name: 'keyword.control.cure' }, 2: { name: 'variable.other.property.cure' } },
        },
        {
          match: '^\\s*(accepts|expands|explain|fail|open|includes|keyword)\\b',
          captures: { 1: { name: 'keyword.control.cure' } },
        },
        { match: '\\b(becomes|contextual|expands)\\b', name: 'keyword.control.cure' },
        // Required family field / container use site: `root ModuleName`
        {
          match: `^\\s*(${PLAIN_IDENT})\\s+(${TYPE})\\s*$`,
          captures: { 1: { name: 'variable.other.property.cure' }, 2: { name: 'entity.name.type.cure' } },
        },
        // Holes in rules: `<name: ModuleName>`, and their category: `> is Statement`
        {
          match: `(?<=<)(${IDENT})(?=\\s*:)`,
          captures: { 1: { name: 'variable.parameter.cure' } },
        },
        { match: '(?<=>)\\s*(is)\\b', captures: { 1: { name: 'keyword.control.cure' } } },
      ],
    },

    // `@extern(...)`, `@derive ...`, `@linear c : Chan(Cmd)`
    decorators: {
      match: `(@)(${IDENT})`,
      captures: {
        1: { name: 'punctuation.definition.decorator.cure' },
        2: { name: 'entity.name.function.decorator.cure' },
      },
    },

    // FSM transitions: `Locked --coin--> Unlocked`, `Red --Timer--> Green`
    transitions: {
      patterns: [
        {
          match: '(--)([a-zA-Z_][a-zA-Z0-9_]*\\??)',
          captures: {
            1: { name: 'keyword.operator.transition.cure' },
            2: { name: 'entity.name.label.cure' },
          },
        },
        { name: 'keyword.operator.transition.cure', match: '!?-->' },
      ],
    },

    keywords: {
      patterns: [
        { name: 'keyword.control.cure', match: words(controlKeywords) },
        { name: 'keyword.operator.word.cure', match: words(wordOperators) },
      ],
    },

    constants: {
      patterns: [
        { name: 'constant.language.boolean.cure', match: '\\b(?:true|false)\\b' },
        { name: 'constant.language.nil.cure', match: '\\bnil\\b' },
        {
          name: 'support.constant.constructor.cure',
          match: '\\b(?:Ok|Error|Some|None|True|False|Z|S)\\b',
        },
      ],
    },

    atoms: {
      name: 'constant.other.symbol.cure',
      match: ':[a-zA-Z_][a-zA-Z0-9_]*[?!]?',
    },

    numbers: {
      patterns: [
        { name: 'constant.numeric.hex.cure', match: '\\b0[xX][0-9a-fA-F_]+\\b' },
        { name: 'constant.numeric.binary.cure', match: '\\b0[bB][01_]+\\b' },
        { name: 'constant.numeric.octal.cure', match: '\\b0[oO][0-7_]+\\b' },
        {
          name: 'constant.numeric.decimal.cure',
          match: '\\b[0-9][0-9_]*(?:\\.[0-9][0-9_]*)?(?:[eE][+-]?[0-9]+)?\\b',
        },
      ],
    },

    holes: {
      name: 'variable.language.hole.cure',
      match: '\\?[a-zA-Z_][a-zA-Z0-9_]*',
    },

    calls: {
      match: `\\b(${IDENT})(?=\\()`,
      captures: { 1: { name: 'entity.name.function.call.cure' } },
    },

    identifiers: {
      patterns: [
        { name: 'variable.other.quoted.cure', match: '`[^`\\n]*`' },
        { name: 'variable.other.cure', match: `\\b${IDENT}` },
      ],
    },

    types: {
      name: 'entity.name.type.cure',
      match: `\\b${TYPE}\\b`,
    },

    operators: {
      patterns: [
        { name: 'keyword.operator.send.cure', match: '<-\\||✉' },
        { name: 'keyword.operator.pipe.cure', match: '\\|>' },
        { name: 'keyword.operator.arrow.cure', match: '->|=>' },
        { name: 'keyword.operator.range.cure', match: '\\.\\.=?' },
        { name: 'keyword.operator.cure', match: '::|[+\\-*/=<>!|&^~\\\\]+|[:.%$?]' },
      ],
    },

    // Brace groups keep an interpolation's `}` from closing early.
    groups: {
      patterns: [
        {
          begin: '%?\\{',
          end: '\\}',
          beginCaptures: { 0: { name: 'punctuation.section.braces.begin.cure' } },
          endCaptures: { 0: { name: 'punctuation.section.braces.end.cure' } },
          patterns: [{ include: '#code' }],
        },
        { name: 'punctuation.section.parens.cure', match: '\\$?\\(|\\)' },
        { name: 'punctuation.section.brackets.cure', match: '%?\\[|\\]' },
      ],
    },

    punctuation: {
      name: 'punctuation.separator.cure',
      match: '[,;]',
    },
  },
};

const json = JSON.stringify(grammar, null, 2) + '\n';

if (process.argv.includes('--check')) {
  const current = fs.existsSync(OUTPUT) ? fs.readFileSync(OUTPUT, 'utf8') : '';
  if (current !== json) {
    console.error(`${path.relative(process.cwd(), OUTPUT)} is out of date; run npm run build-grammar`);
    process.exit(1);
  }
} else {
  fs.writeFileSync(OUTPUT, json);
}
